-- Canada milestone translations (ES/DE/FR)
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-cra-research-2018', 'es', 'La CRA inicia investigaciones sobre facturación electrónica', 'La Agencia de Ingresos de Canadá (CRA) inicia investigaciones preliminares sobre facturación electrónica, años antes de que surgiera cualquier propuesta concreta.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-watch', 'es', 'La CRA estudia un posible mandato B2B de facturación electrónica (sin mandato promulgado)', 'La Agencia de Ingresos de Canadá realizó una investigación con partes interesadas sobre un posible mandato nacional de facturación electrónica B2B. No se ha promulgado ninguna legislación ni plazo firme: las normas de GST/HST siguen siendo neutrales en cuanto al formato, y las facturas en papel, PDF y EDI son actualmente aceptables siempre que incluyan la información fiscal requerida.', '["No se requiere ninguna acción hoy más allá de una buena práctica de mantenimiento de registros", "Vigilar futuros anuncios de la CRA / Finance Canada, especialmente a medida que crece la adopción de la red DBNAlliance en Canadá"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-federal-b2g', 'es', 'Todos los proveedores del gobierno federal deben facturar electrónicamente (B2G, vigente desde 2022)', 'Desde abril de 2022, Public Services and Procurement Canada (PSPC) exige que los proveedores presenten facturas electrónicamente a través de su solución de contratación electrónica basada en SAP Ariba. No existe un mandato federal de facturación electrónica B2B.', '["Si usted es proveedor del Gobierno de Canadá, regístrese en SAP Ariba a través de CanadaBuys", "Conserve las facturas electrónicas durante al menos 6 años según los requisitos de conservación de registros de la CRA"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-regulatory-plan-2025', 'es', 'Los planes regulatorios de la CRA enumeran iniciativas de reporte digital, pero no mencionan la facturación electrónica por su nombre', 'El plan regulatorio prospectivo de la CRA incluye varias normas de reporte digital para este período, pero ninguna nombra explícitamente un mandato de facturación electrónica, una señal de que el tema sigue en la agenda sin un plazo comprometido.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-cra-research-2018', 'de', 'CRA startet Untersuchungen zur elektronischen Rechnungsstellung', 'Die kanadische Steuerbehörde (CRA) beginnt mit ersten Untersuchungen zur elektronischen Rechnungsstellung – Jahre bevor ein konkreter Vorschlag folgen würde.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-watch', 'de', 'CRA prüft ein mögliches B2B-E-Invoicing-Mandat (kein Mandat erlassen)', 'Die kanadische Steuerbehörde (CRA) führte eine Stakeholder-Untersuchung zu einem möglichen inländischen B2B-E-Invoicing-Mandat durch. Es folgten weder eine Gesetzgebung noch ein fester Zeitplan – die GST/HST-Regeln bleiben formatneutral, und Papier-, PDF- und EDI-Rechnungen sind derzeit alle zulässig, sofern sie die erforderlichen Steuerinformationen enthalten.', '["Über eine gute Aufbewahrungspraxis hinaus ist derzeit keine Maßnahme erforderlich", "Zukünftige Ankündigungen von CRA / Finance Canada beobachten, insbesondere da die Nutzung des DBNAlliance-Netzwerks in Kanada wächst"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-federal-b2g', 'de', 'Alle Lieferanten der Bundesregierung müssen elektronisch fakturieren (B2G, in Kraft seit 2022)', 'Seit April 2022 verlangt Public Services and Procurement Canada (PSPC) von Lieferanten, Rechnungen elektronisch über die SAP-Ariba-basierte E-Procurement-Lösung einzureichen. Es besteht kein bundesweites B2B-E-Invoicing-Mandat.', '["Wenn Sie die kanadische Regierung beliefern, registrieren Sie sich über CanadaBuys in SAP Ariba", "Bewahren Sie elektronische Rechnungen gemäß den CRA-Aufbewahrungspflichten mindestens 6 Jahre lang auf"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-regulatory-plan-2025', 'de', 'CRAs Regulierungspläne listen Initiativen zur digitalen Meldung – aber E-Invoicing wird nicht namentlich genannt', 'CRAs vorausschauender Regulierungsplan enthält für diesen Zeitraum verschiedene Regeln zur digitalen Meldung, aber keine nennt explizit ein E-Invoicing-Mandat – ein Zeichen, dass das Thema ohne festen Zeitplan weiter auf der Agenda bleibt.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-cra-research-2018', 'fr', 'L''ARC lance des recherches sur la facturation électronique', 'L''Agence du revenu du Canada (ARC) entame des recherches préliminaires sur la facturation électronique, des années avant qu''une proposition concrète ne voie le jour.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-watch', 'fr', 'L''ARC étudie un éventuel mandat B2B de facturation électronique (aucun mandat adopté)', 'L''Agence du revenu du Canada a mené une recherche auprès des parties prenantes sur un éventuel mandat national de facturation électronique B2B. Aucune législation ni échéancier ferme n''a suivi — les règles de TPS/TVH restent neutres quant au format, et les factures papier, PDF et EDI sont toutes actuellement acceptées à condition de comporter les informations fiscales requises.', '["Aucune action n''est requise aujourd''hui au-delà d''une bonne tenue des registres", "Surveiller les futures annonces de l''ARC / Finances Canada, notamment à mesure que l''adoption du réseau DBNAlliance progresse au Canada"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-federal-b2g', 'fr', 'Tous les fournisseurs du gouvernement fédéral doivent facturer électroniquement (B2G, en vigueur depuis 2022)', 'Depuis avril 2022, Services publics et Approvisionnement Canada (SPAC) exige que les fournisseurs soumettent leurs factures électroniquement via sa solution d''approvisionnement électronique basée sur SAP Ariba. Il n''existe aucun mandat fédéral de facturation électronique B2B.', '["Si vous approvisionnez le gouvernement du Canada, inscrivez-vous sur SAP Ariba via CanadaBuys", "Conservez les factures électroniques pendant au moins 6 ans conformément aux exigences de conservation des registres de l''ARC"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ca-regulatory-plan-2025', 'fr', 'Le plan de réglementation de l''ARC répertorie des initiatives de déclaration numérique — mais pas la facturation électronique nommément', 'Le plan de réglementation prospectif de l''ARC inclut diverses règles de déclaration numérique pour cette période, mais aucune ne nomme explicitement un mandat de facturation électronique — un signe que le sujet reste à l''ordre du jour sans échéancier ferme.', '[]');
